import { revalidatePath } from "next/cache";

// Mock database to hold the user's notification preference
let notificationsEnabled = false;

// Server Action to toggle the preference
async function toggleNotification() {
  "use server";

  // 1. Update the database/state
  notificationsEnabled = !notificationsEnabled;

  // 2. Revalidate the path to refresh the current page and show the updated 
  // preference without triggering a redirect or a hard page reload.
  revalidatePath("/");
}

export default function Home() {
  return (
    <main style={{ padding: "2rem", fontFamily: "sans-serif" }}>
      <h1>Settings</h1>

      <p>
        Notifications are currently:{" "}
        <strong>{notificationsEnabled ? "ON" : "OFF"}</strong>
      </p>

      {/* 
        Using a form action is Next.js's recommended approach to invoke 
        Server Actions, ensuring it works even before JS loads. 
      */}
      <form action={toggleNotification}>
        <button 
          type="submit" 
          style={{ padding: "0.5rem 1rem", cursor: "pointer", marginTop: "1rem" }}
        >
          Toggle Notifications
        </button>
      </form>
    </main>
  );
}

